mapper.select:
SELECT pc.id AS customerId, pc.name AS childName, pc.birth_date AS childBirthDate, TIMESTAMPDIFF(YEAR, pc.birth_date, CURDATE()) AS childAge, TIMESTAMPDIFF(MONTH, pc.birth_date, CURDATE()) AS childAgeMonth, parent.integrated_customer_id AS parentCustomerId, parent.name AS parentName, TIMESTAMPDIFF(YEAR, parent.birth_date, CURDATE()) AS parentAge, parent.phone AS parentPhone, parent.address AS parentAddress, pc.gender AS childGender, pc.relationship_code AS relationCode, pc.consult_status_code AS consultStatusCode, consult_code.code_name AS consultStatusName, relation_code.code_name AS relationName, sales_user.id AS salesUserId, sales_user.name AS salesUserName, sales_user.phone AS salesUserPhone, sales_user.email AS salesUserEmail FROM potential_customer pc INNER JOIN integrated_customer parent ON parent.integrated_customer_id = pc.parent_customer_id LEFT JOIN sales_user ON sales_user.id = pc.sales_user_id LEFT JOIN common_code relation_code ON relation_code.group_code = 'RELATIONSHIP' AND relation_code.code_value = pc.relationship_code LEFT JOIN common_code consult_code ON consult_code.group_code = 'CONSULT_STATUS' AND consult_code.code_value = pc.consult_status_code WHERE #{conversionStatusCode} = '01' AND pc.id = #{customerId} AND pc.is_active = FALSE
UNION ALL
SELECT child.integrated_customer_id AS customerId, child.name AS childName, child.birth_date AS childBirthDate, TIMESTAMPDIFF(YEAR, child.birth_date, CURDATE()) AS childAge, TIMESTAMPDIFF(MONTH, child.birth_date, CURDATE()) AS childAgeMonth, parent.integrated_customer_id AS parentCustomerId, parent.name AS parentName, TIMESTAMPDIFF(YEAR, parent.birth_date, CURDATE()) AS parentAge, parent.phone AS parentPhone, parent.address AS parentAddress, child.gender AS childGender, NULL AS relationCode, NULL AS consultStatusCode, NULL AS consultStatusName, '보호자' AS relationName, sales_user.id AS salesUserId, sales_user.name AS salesUserName, sales_user.phone AS salesUserPhone, sales_user.email AS salesUserEmail FROM integrated_customer child LEFT JOIN integrated_customer parent ON parent.integrated_customer_id = child.parent_id LEFT JOIN sales_user ON sales_user.id = child.sales_user_id WHERE #{conversionStatusCode} = '02' AND child.integrated_customer_id = #{customerId}

SELECT COUNT(*)
FROM (
    SELECT pc.id AS customer_id
    FROM potential_customer pc
    WHERE #{conversionStatusCode} = '01'
      AND pc.id = #{customerId}
      AND pc.sales_user_id = #{salesUserId}

    UNION ALL

    SELECT ic.integrated_customer_id AS customer_id
    FROM integrated_customer ic
    WHERE #{conversionStatusCode} = '02'
      AND ic.integrated_customer_id = #{customerId}
      AND ic.sales_user_id = #{salesUserId}
) report_target
